// Normalize lead data from Webflow, WordPress, or direct POST
const body = $input.first().json.body || $input.first().json;

const lead = {
  firstName: body.first_name || body.firstName || body.name?.split(' ')[0] || 'Unknown',
  lastName: body.last_name || body.lastName || body.name?.split(' ')[1] || '',
  email: body.email || body.Email || '',
  phone: body.phone || body.Phone || body.phone_number || '',
  company: body.company || body.Company || body.company_name || '',
  jobTitle: body.job_title || body.jobTitle || body.role || '',
  companySize: body.company_size || body.companySize || body.employees || '',
  budget: body.budget || body.Budget || '',
  industry: body.industry || body.Industry || '',
  message: body.message || body.Message || body.how_can_we_help || '',
  website: body.website || body.Website || body.company_website || '',
  source: body.source || body._source || 'webform',
  submittedAt: new Date().toISOString()
};

// Basic validation
if (!lead.email) {
  throw new Error('Lead missing email address — cannot process.');
}

return [{ json: lead }];

