const lead = $('Normalize Lead Data').first().json;
const rawContent = $input.first().json.choices[0].message.content;

// Strip markdown code fences if present
const cleaned = rawContent.replace(/```json|```/g, '').trim();
let qualification;
try {
  qualification = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Failed to parse GPT-4o qualification JSON: ' + rawContent);
}

return [{
  json: {
    lead,
    qualification: {
      score: qualification.score || 0,
      tier: qualification.tier || 'cold',
      reasoning: qualification.reasoning || '',
      detectedPainPoints: qualification.detectedPainPoints || [],
      companySignals: qualification.companySignals || [],
      decisionMakerLikelihood: qualification.decisionMakerLikelihood || 'low'
    }
  }
}];

