const upstream = $('Parse Qualification Result').first().json;
const rawContent = $input.first().json.choices[0].message.content;
const cleaned = rawContent.replace(/```json|```/g, '').trim();
let emailDraft;
try {
  emailDraft = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Failed to parse warm email JSON');
}
return [{ json: { ...upstream, emailDraft } }];

const data = $('Parse Qualification Result').first().json;
console.log(`[COLD LEAD] ${data.lead.email} scored ${data.qualification.score} — added to cold nurture sequence.`);
return [{ json: { ...data, action: 'cold_nurture_sequence', status: 'queued' } }];

// Final log node — all paths converge here for audit logging
const items = $input.all();
const results = items.map(item => ({
  email: item.json?.lead?.email || 'unknown',
  tier: item.json?.qualification?.tier || 'unknown',
  score: item.json?.qualification?.score || 0,
  action: item.json?.action || 'full_outreach',
  processedAt: new Date().toISOString()
}));
console.log('[LEAD ENGINE] Processed:', JSON.stringify(results, null, 2));
return items;
